            x //= d
        d += 1 if d == 2 else 2
    if x > 1:
        fac[x] = fac.get(x, 0) + 1
    return fac  # dict prime -> exponent

def coprime_count_up_to(N, b):
    # Count of integers 1..N that are coprime to b via inclusion-exclusion on prime divisors of b.
    if N <= 0:
        return 0
    fac = factorize(b)
    primes = list(fac.keys())
    if not primes:
        return N
    m = len(primes)
    total = 0
    # Inclusion-exclusion over subsets of primes
    for mask in range(1 << m):
        mult = 1
        bits = 0
        for i in range(m):
            if mask & (1 << i):
                mult *= primes[i]
                bits += 1
        cnt = N // mult
        if bits % 2 == 0:
            total += cnt
        else:
            total -= cnt
    return total

