    # v_p(m!) via Legendre's formula
    s = 0
    pp = p
    while pp <= m:
        s += m // pp
        # avoid overflow
        if pp > m // p:
            break
        pp *= p
    return s

def smarandache_prime_power(p, e):
    # Least m such that v_p(m!) >= e. Binary search using doubling upper bound.
    if e <= 0:
        return 1
    lo = 1
    hi = max(p * e, 2)
    # Ensure hi is sufficient
    while vp_factorial(hi, p) < e:
        hi *= 2
        if hi > 10**9:
            break
    while lo < hi:
        mid = (lo + hi) // 2
        if vp_factorial(mid, p) >= e:
            hi = mid
        else:
            lo = mid + 1
    return lo

